'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {chromium}=require('playwright');
const html=fs.readFileSync(path.resolve(__dirname,'../../index.html'),'utf8');
const css=[...html.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/gi)].map(m=>m[1]).join('\n');
const source=html.slice(html.indexOf('function plannerAgendaColumnHeight('),html.indexOf('function buildPlannerYearContinuousCanvas('));
const fixture=`<!doctype html><meta charset="utf-8"><style>:root{--t-surface:#fff;--t-surface-2:#edf5ef;--t-bg:#fff;--t-line:#d6ded8;--t-muted:#68756e;--t-ink:#153327;--t-text:#24372d;--t-shadow:rgba(0,0,0,.05);--t-shadow-soft:rgba(0,0,0,.03);--ds-radius-float:18px;--ds-shadow-float:0 20px 60px rgba(0,0,0,.18)}body{margin:0;background:#eef2ef}</style><style>${css}</style><div class="export-center-panel planner-year-showcase-panel" id="plannerYearShowcasePanel" style="right:12px;top:12px;max-height:calc(100vh - 24px)"><header class="export-center-head"><div><strong>全年排期展示</strong></div><button class="export-center-close" aria-label="关闭">×</button></header><div class="export-composer-body"><div class="export-composer-grid"><div class="export-composer-controls"><section class="export-center-section"><strong>导出形式</strong><div class="stats-segmented"><button>自动分页</button><button class="active">单张长图</button></div></section><section class="export-center-section"><strong>展示方式</strong><div class="stats-segmented planner-year-mode-switch"><button>年度总览</button><button>完整年历</button><button class="active">排期清单</button></div></section><div class="export-center-summary">2026 · 66 场 / 46 个排期日 / 42 桌</div></div><aside class="export-preview-pane"><div class="export-preview-head"><strong>实时预览</strong></div><div id="plannerYearShowcasePreview" class="export-preview-stage planner-year-preview-stage"><div class="export-live-preview-page"><canvas id="agenda" width="1600" height="1400"></canvas></div></div></aside></div></div><footer class="export-center-foot"><button class="btn">恢复默认</button><button class="btn primary">导出图片</button></footer></div>`;
const setup=source+`\nfunction defaultPlannerYearShowcaseState(){return {showPc:false,showHo:false,showExactTime:false};}\nfunction canvasFillRound(ctx,x,y,w,h,r,fill,stroke){ctx.fillStyle=fill;ctx.fillRect(x,y,w,h);}\nfunction drawStatsStoryPanelBase(ctx,x,y,w,h,t){canvasFillRound(ctx,x,y,w,h,12,t.surface,t.line);return y+82;}\nfunction canvasTextFit(ctx,s){return String(s);}\nfunction statsEventRoleLabel(){return 'PL';}\nconst data={events:[],state:{showPc:false,showHo:false,showExactTime:false}};for(let m=7;m<=12;m++)for(let i=0;i<11;i++)data.events.push({date:'2026-'+String(m).padStart(2,'0')+'-'+String(i%28+1).padStart(2,'0'),moduleName:'模组',archived:true});const layout=plannerAgendaLayout(data,1532),canvas=document.getElementById('agenda'),ctx=canvas.getContext('2d'),monthHeads=[],fillText=ctx.fillText.bind(ctx);ctx.fillText=(s,x,y)=>{if(/月 · \\d+ 场/.test(s))monthHeads.push({s,x,y});fillText(s,x,y);};canvas.height=180+layout.panelH+72;ctx.fillStyle='#fff';ctx.fillRect(0,0,1600,canvas.height);drawPlannerYearAgendaBlock(ctx,34,180,1532,{surface:'#fff',surface2:'#edf5ef',line:'#c9dacf',ink:'#183327',muted:'#63746a'},data);window.agendaProbe={layout:{left:layout.left,right:layout.right,panelH:layout.panelH},monthHeads,canvasH:canvas.height};`;
(async()=>{const browser=await chromium.launch({headless:true,args:['--no-sandbox'],...(process.env.PL_CI_CHROMIUM_EXECUTABLE?{executablePath:process.env.PL_CI_CHROMIUM_EXECUTABLE}:{})});try{for(const [w,h] of [[1440,900],[900,740],[853,675],[390,844],[320,568]]){const page=await browser.newPage({viewport:{width:w,height:h}}),errors=[];page.on('pageerror',e=>errors.push(String(e)));try{await page.setContent(fixture);await page.evaluate(`(()=>{${setup}})()`);const v=await page.evaluate(()=>{const q=s=>document.querySelector(s),r=s=>{const b=q(s).getBoundingClientRect();return{left:b.left,right:b.right,top:b.top,bottom:b.bottom,height:b.height}};return{panel:r('#plannerYearShowcasePanel'),head:r('.export-center-head'),body:r('.export-composer-body'),foot:r('.export-center-foot'),pane:r('.export-preview-pane'),stage:r('#plannerYearShowcasePreview'),canvas:r('#agenda'),backgrounds:['#plannerYearShowcasePanel','.export-composer-body','.export-preview-pane','#plannerYearShowcasePreview'].map(s=>getComputedStyle(q(s)).backgroundColor),overflow:document.documentElement.scrollWidth-innerWidth,probe:window.agendaProbe};});assert.equal(errors.length,0,JSON.stringify(errors));assert(v.overflow<=1&&v.panel.right<=w+1&&v.panel.bottom<=h+1,`${w}: modal overflow ${JSON.stringify(v)}`);assert(v.body.height>=100,`${w}: body squeezed`);assert(v.backgrounds.every(x=>x==='rgb(255, 255, 255)'),`${w}: white background discontinuity ${v.backgrounds}`);assert.deepEqual(v.probe.layout.left,[7,8,9]);assert.deepEqual(v.probe.layout.right,[10,11,12]);assert.equal(v.probe.monthHeads.length,6);assert(v.probe.monthHeads.some(x=>x.x<800)&&v.probe.monthHeads.some(x=>x.x>800),'both columns populated');assert(v.probe.canvasH===180+v.probe.layout.panelH+72);if(w===853)assert(v.pane.left>v.body.left&&v.pane.top<v.foot.top,'desktop two-column preview preserved');console.log(`${w}x${h}: planner agenda balanced, measured white background and aligned preview pass`);}catch(err){const dir=process.env.PL_SYNTHETIC_REPORT_DIR;if(dir){fs.mkdirSync(dir,{recursive:true});await page.screenshot({path:path.join(dir,`round143-${w}x${h}-failure.png`)});}throw err;}finally{await page.close();}}}finally{await browser.close();}})().catch(err=>{console.error(err.stack||err);process.exitCode=1});
